      <div class="card-meta">
        <span class="pay-estimate">当前: ¥${price.toFixed(1)}</span>
        <span class="slot-tag">${good.category}</span>
      </div>
      <div class="flex gap-2 mt-2">
        <button class="btn btn-sm btn-success buy-goods" data-good="${good.id}">买</button>
        <button class="btn btn-sm btn-danger sell-goods" data-good="${good.id}">卖</button>
      </div>
    `;
    grid.appendChild(card);
  }

  div.appendChild(grid);

  // 绑定事件
  setTimeout(() => {
    parent.querySelectorAll('.buy-goods').forEach(btn => {
      btn.addEventListener('click', () => {
        const goodId = btn.dataset.good;
        if (typeof buyGood === 'function') {
          buyGood(goodId, 1);
          renderAll();
        }
