/**
 * 装备/道具定义
 */

const ITEMS = [
  { id: 'straw_hat',       name: '草帽',       slot: 'head',   effects: { hygiene: 2 },          price: 10 },
  { id: 'work_gloves',     name: '劳保手套',   slot: 'hand',   effects: { physique: 3, injury: -0.02 }, price: 15 },
  { id: 'mask',            name: '口罩',       slot: 'head',   effects: { hygiene: 5, illness: -0.03 }, price: 5 },
  { id: 'sturdy_shoes',    name: '解放鞋',     slot: 'feet',   effects: { agility: 3, fatigue: -5 },  price: 25 },
  { id: 'backpack',        name: '大背包',     slot: 'accessory', effects: { capacity: 10 },        price: 40 },
