/**
 * 职场行动执行引擎
 */

/** 执行职场行动 */
function doCorporateAction(actionId) {
  const state = StateManager.getState();
  const action = CORP_ACTIONS.find(a => a.id === actionId);
  if (!action) return false;

  // 检查职级要求
  if (action.requiresRank) {
    const rankIndex = ['P5','P6','P7','P8','P9','P10'].indexOf(state.corporate.rank);
    const requiredIndex = ['P5','P6','P7','P8','P9','P10'].indexOf(action.requiresRank);
    if (rankIndex < requiredIndex) {
      StateManager.addMessage(`⚠️ 需要${action.requiresRank}以上才能执行此操作。`, 'warning');
      return false;
    }
  }

  // 检查费用
  if (action.cost && state.resources.cash < action.cost) {
    StateManager.addMessage(`⚠️ 需要 ¥${action.cost}，现金不足。`, 'warning');
    return false;
  }

  // 特殊处理：股票交易
  if (action.special === 'stock') {
    showStockTradeModal();
    return true;
  }

  // 扣费
  if (action.cost) {
    state.resources.cash -= action.cost;
  }

  // 应用效果
  const c = state.player.corporate;
  const effects = action.effects;
  if (effects.kpi) c.kpi = Math.max(0, Math.min(150, c.kpi + effects.kpi));
  if (effects.ability) c.ability = Math.max(0, Math.min(100, c.ability + effects.ability));
  if (effects.hair) c.hair = Math.max(0, Math.min(100, c.hair + effects.hair));
  if (effects.dignity) c.dignity = Math.max(0, Math.min(100, c.dignity + effects.dignity));
  if (effects.upwardMgmt) c.upwardMgmt = Math.max(0, Math.min(100, c.upwardMgmt + effects.upwardMgmt));
  if (effects.popularity) c.popularity = Math.max(0, Math.min(100, c.popularity + effects.popularity));
  if (effects.risk) c.risk = Math.max(0, Math.min(100, c.risk + effects.risk));
  if (effects.fatigue) state.needs.fatigue = Math.max(0, Math.min(100, state.needs.fatigue + effects.fatigue));
  if (effects.happiness) state.needs.happiness = Math.max(0, Math.min(100, state.needs.happiness + effects.happiness));
  if (effects.intelligence) state.player.intelligence = Math.min(100, state.player.intelligence + effects.intelligence);

  state.corporate.actionsUsed++;
  StateManager.addMessage(`${action.icon} ${action.name}完成！`, 'success');

  // 检查季度是否用完
  const rankData = CORP_RANKS[state.corporate.rank];
  const maxActions = rankData ? rankData.maxActions : 3;
  if (state.corporate.actionsUsed >= maxActions) {
    endQuarter();
  }

  return true;
}

/** 季度结束 */
function endQuarter() {
  const state = StateManager.getState();
  const c = state.corporate;

  // 绩效考核
  const perfResult = calculatePerfScore(state);
  const grade = assignGrade(perfResult.score, state);
  c.perfHistory.push({
    year: state.player.corpYear,
    quarter: state.player.corpQuarter,
    grade: grade.grade,
    score: perfResult.score,
  });

  // 追踪连续C
  if (grade.grade === 'C') {
    c.consecutiveC++;
  } else {
    c.consecutiveC = 0;
  }

  // 发放季度工资
  const rankData = CORP_RANKS[c.rank];
  const salary = rankData ? rankData.baseSalary * 3 : 45000;
  state.resources.cash += salary;
  state.resources.totalEarned += salary;

  StateManager.addMessage(`💰 Q${c.corpQuarter} 结束。工资到账 ¥${salary.toLocaleString()}。绩效: ${grade.grade}`, 'success');

  // Q3 晋升判定
  if (c.corpQuarter === 3) {
    const promoResult = checkPromotion(state);
    if (promoResult) {
      applyPromotion(state, promoResult);
    }
  }

  // 职场随机事件
  if (Math.random() < 0.2) {
    rollCorporateEvent(state);
  }

  // 推进季度
  c.actionsUsed = 0;
  if (c.corpQuarter >= 4) {
    c.corpQuarter = 1;
    state.player.corpYear++;
    state.player.age++;
    StateManager.addMessage(`🎂 又一年过去了，你现在${state.player.age}岁了。`, 'event');
  } else {
    c.corpQuarter++;
  }

  // 失败条件
  checkCorpLoseConditions(state);
  // 胜利条件
  checkCorpWinConditions(state);

  autoSave();
}

/** 进入职场阶段 */
function enterCorporatePhase(companyId) {
  const state = StateManager.getState();
  const p = state.player;

  const company = COMPANIES.find(c => c.id === (companyId || 'star_tech')) || COMPANIES[0];

  p.phase = 'corporate';
  p.corpYear = 1;
  p.corpQuarter = 1;

  p.corporate.hair = 100;
  p.corporate.dignity = Math.min(100, Math.round(p.mental * 1.2));
