function endDay() {
  const state = StateManager.getState();

  state.player.day++;

  // 需求衰减
  state.needs.hunger = Math.max(0, state.needs.hunger - 18);
  state.needs.hygiene = Math.max(0, state.needs.hygiene - 8);
  state.needs.fatigue = Math.max(0, state.needs.fatigue - 25); // 睡眠恢复
  state.needs.happiness = Math.max(0, state.needs.happiness - 3);

  // 健康自然恢复
  if (!state.status.sick && !state.status.injured) {
    state.status.health = Math.min(100, state.status.health + 1);
  }

  // 伤病影响
  if (state.status.sick) {
    state.status.health = Math.max(0, state.status.health - 3);
    if (Math.random() < 0.1) state.status.sick = false; // 10% 自愈
  }
  if (state.status.injured) {
    state.status.health = Math.max(0, state.status.health - 2);
    if (Math.random() < 0.05) state.status.injured = false;
  }

  // 饥饿/卫生极端惩罚
  if (state.needs.hunger < 15) {
    state.status.health = Math.max(0, state.status.health - 5);
    StateManager.addMessage('⚠️ 你已经饿得不行了！健康-5。快去吃点什么！', 'danger');
  }
  if (state.needs.hygiene < 15) {
    state.status.health = Math.max(0, state.status.health - 5);
    StateManager.addMessage('⚠️ 身上太脏了，开始生病！健康-5。去洗个澡吧。', 'danger');
  }

  // 贷款利息
  if (state.resources.debt > 0) {
    const interest = Math.floor(state.resources.debt * state.resources.dailyInterest);
    if (interest > 0) {
      state.resources.debt += interest;
      StateManager.addMessage(`🏦 欠款利息：+¥${interest}（当前欠款 ¥${state.resources.debt.toLocaleString()}）`, 'warning');
    }
  }

  // 银行存款利息
  if (state.resources.bankBalance > 0) {
    const bankInterest = Math.floor(state.resources.bankBalance * 0.001); // 日息 0.1%
    if (bankInterest > 0) {
      state.resources.bankBalance += bankInterest;
    }
  }

  // 每3天更新价格
  if (state.player.day - state.trade.lastPriceUpdate >= 3) {
    updateAllPrices(state);
  }

  // 随机事件（10%概率）
  if (Math.random() < 0.1) {
    triggerRandomEvent(state);
  }

  // 每年年龄增长
  if (state.player.day % 365 === 0) {
    state.player.age++;
    StateManager.addMessage(`🎂 又过了一年，你现在${state.player.age}岁了。`, 'event');
  }

  // 失败条件检查
  checkLoseConditions(state);

  // 自动存档
  autoSave();

  StateManager.addMessage(`🌙 第${state.player.day}天结束了。新的一天开始。`, 'info');
}

/** 随机事件 */
function triggerRandomEvent(state) {
  const events = [
    { text: '街头有人发传单，给了你一张优惠券（没用）', type: 'info' },
    { text: '看到路边有人在摆摊，生意好像不错', type: 'info' },
    { text: '天气突然变冷，街上的行人少了', type: 'info' },
    { text: '邻居向你抱怨最近废品价格又跌了', type: 'warning' },
  ];
  const evt = events[Math.floor(Math.random() * events.length)];
  StateManager.addMessage(`📰 ${evt.text}`, evt.type);
}

/** 失败条件检查 */
function checkLoseConditions(state) {
  if (state.status.health <= 0) {
    state.flags.gameOver = true;
    state.flags.gameOverReason = '健康耗尽，你倒在了这座城市的街头...';
    showGameOverModal();
  }
  if (state.resources.debt > 50000) {
    state.flags.gameOver = true;
    state.flags.gameOverReason = '债务超过5万元，讨债的人找上门来...';
    showGameOverModal();
  }
}

