  const travelActions = actions.filter(a => a.id.startsWith('travel_'));
  const housingActions = actions.filter(a => a.id.startsWith('housing_') || a.id.startsWith('storage_'));
  const otherActions = actions.filter(a => !a.id.startsWith('travel_') && !a.id.startsWith('housing_') && !a.id.startsWith('storage_'));

  // === 🌍 出行区域（置顶，醒目） ===
  if (travelActions.length > 0) {
    const travelSection = document.createElement('div');
    travelSection.style.cssText = 'margin-bottom:16px;';
    travelSection.innerHTML = '<h3 style="color:var(--accent);margin-bottom:8px;font-size:14px;">🌍 出行 — 点击前往其他地点</h3>';

    const travelGrid = document.createElement('div');
    travelGrid.className = 'action-cards';
    travelGrid.style.gridTemplateColumns = 'repeat(auto-fill, minmax(180px, 1fr))';

    for (const action of travelActions) {
      const destKey = action.id.replace('travel_', '');
      const dest = typeof getLocation === 'function' ? getLocation(destKey) : null;
      const jobCount = dest ? (dest.jobs || []).length : 0;

      // 检查该地点的最佳买卖机会
      let tradeHint = '';
      if (typeof GOODS !== 'undefined' && state.trade.goodsPrices[destKey]) {
        const opportunities = [];
        for (const good of GOODS) {
          const destPrice = state.trade.goodsPrices[destKey]?.[good.id];
          const curPrice = state.trade.goodsPrices[state.trade.currentLocation]?.[good.id];
          if (destPrice && curPrice && destPrice > curPrice * 1.3) {
            opportunities.push(`${good.name}📈`);
          }
        }
        if (opportunities.length > 0) tradeHint = `<br>🤑 可卖: ${opportunities.slice(0,2).join(' ')}`;
      }

      const card = document.createElement('div');
      card.className = 'action-card';
      card.style.borderColor = 'var(--accent)';
      card.style.background = 'linear-gradient(135deg, var(--bg-card), rgba(0,180,216,0.05))';
      card.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;">
          <div class="card-title" style="font-size:15px;color:var(--accent);">${dest ? dest.name : destKey}</div>
          <span style="font-size:10px;color:var(--text-muted);">🚶 前往</span>
